parameters.jsCode:
// 1. Extraemos el cuerpo que envía Slack a través del Webhook
const body = $input.first().json.body;

// 2. Leemos la propiedad payload
let rawPayload = body.payload;
if (typeof rawPayload === 'string') {
  try {
    rawPayload = JSON.parse(decodeURIComponent(rawPayload));
  } catch (e) {
    rawPayload = JSON.parse(rawPayload);
  }
}

// 3. Extraemos el usuario que hizo clic y el valor guardado en el botón
const usuarioSlack = rawPayload.user ? (rawPayload.user.name || rawPayload.user.username) : 'Desconocido';
const actionValue = rawPayload.actions && rawPayload.actions[0] ? rawPayload.actions[0].value : '';

// 4. Separamos por "|" y limpiamos espacios de cada elemento
const parts = actionValue.split('|').map(p => p.trim());

/* 
  Estructura limpia esperada (8 elementos):
  parts[0] -> accion
  parts[1] -> airtableId
  parts[2] -> canal_destino
  parts[3] -> fecha_deseada
  parts[4] -> email
  parts[5] -> telefono
  parts[6] -> nombre_apellido
  parts[7] -> ai_output
*/

const accion = parts[0] || 'desconocido';
const airtableId = parts[1] || null;
const canalSlack = parts[2] || (rawPayload.channel ? (rawPayload.channel.id || rawPayload.channel.name) : null);
const fechaDeseada = parts[3] || null;
const email = parts[4] || null;
const telefono = parts[5] || null;
const nombreApellido = parts[6] || null;
const aiOutput = parts[7] || null;

// 5. Devolvemos el objeto mapeado correctamente
return {
  json: {
    accion: accion,
    airtableId: airtableId,
    canal_destino: canalSlack,
    fecha_deseada: fechaDeseada,
    email: email,
    telefono: telefono,
    nombre_apellido: nombreApellido,
    ai_output: aiOutput,
    usuario_slack: usuarioSlack
  }
};

